import { builtinsTypes } from 'pg-types';
export interface PostgresColumnDefinition<T> {
    name: Extract<keyof T, string>;
    dataType: builtinsTypes | 'SERIAL';
    /** sql-ts def */
    property?: string;
    autoGenerated?: boolean;
    primaryKey?: boolean;
    references?: string | {
        table?: string;
        column?: string;
        constraint?: string;
        onDelete?: 'restrict' | 'cascade' | 'no action' | 'set null' | 'set default';
        onUpdate?: 'restrict' | 'cascade' | 'no action' | 'set null' | 'set default';
    };
    notNull?: boolean;
    unique?: boolean;
    defaultValue?: any;
    subfields?: string[];
}
